-- Hontrix-PDTR: complete database setup (11 migrations). Generated by scripts/build-sql.mjs — do not edit by hand.
-- ═══════════ 0001_core_schema.sql ═══════════
-- Hontrix-PDTR — Milestone 1: core schema (tenancy, customers, vehicles, loans,
-- repayment ledger, documents, audit). Money is numeric(14,2) in INR.
-- Every business row carries financier_id; composite FKs keep related rows in one tenant.

create type app_role         as enum ('platform_admin','owner','employee');
create type customer_status  as enum ('active','inactive','blocked');
create type vehicle_category as enum ('car','commercial','truck','pickup','two_wheeler','other');
create type loan_status      as enum ('application','under_review','approved','rejected','disbursed','active','overdue','closed','restructured');
create type interest_method  as enum ('flat','reducing');
create type payment_frequency as enum ('weekly','fortnightly','monthly');
create type payment_kind     as enum ('receipt','reversal');
create type payment_method   as enum ('cash','upi','bank_transfer','cheque','other');
create type document_category as enum ('rc','insurance','kyc','address_proof','pan','loan_application','loan_agreement','promissory_note','hypothecation','payment_receipt','other');
create type document_status  as enum ('missing','uploaded','pending_review','verified','rejected','expired','needs_attention');

create function today_ist() returns date language sql stable as
$$ select (now() at time zone 'Asia/Kolkata')::date $$;

-- ───────────── tenants and users ─────────────
create table financiers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table profiles (
  id uuid primary key references auth.users(id) on delete restrict,
  financier_id uuid references financiers(id),
  role app_role not null,
  full_name text not null,
  phone text,
  -- employee permissions: customers.write, vehicles.write, loans.write, payments.record,
  -- payments.reverse, documents.upload, documents.verify. Owners implicitly hold all.
  permissions text[] not null default '{}',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  check ((role = 'platform_admin') = (financier_id is null))
);

create function auth_financier_id() returns uuid language sql stable security definer set search_path = public as
$$ select financier_id from profiles where id = auth.uid() and is_active $$;

create function auth_role() returns app_role language sql stable security definer set search_path = public as
$$ select role from profiles where id = auth.uid() and is_active $$;

create function has_permission(p text) returns boolean language sql stable security definer set search_path = public as
$$ select exists (select 1 from profiles
                  where id = auth.uid() and is_active and financier_id is not null
                    and (role = 'owner' or p = any(permissions))) $$;

create table id_counters (
  financier_id uuid not null references financiers(id),
  kind text not null,
  last_value bigint not null default 0,
  primary key (financier_id, kind)
);

create function next_code(p_kind text, p_prefix text) returns text
language plpgsql security definer set search_path = public as $$
declare v_fin uuid := auth_financier_id(); v bigint;
begin
  if v_fin is null then raise exception 'no financier context' using errcode = '42501'; end if;
  insert into id_counters(financier_id, kind, last_value) values (v_fin, p_kind, 1)
  on conflict (financier_id, kind) do update set last_value = id_counters.last_value + 1
  returning last_value into v;
  return p_prefix || lpad(v::text, 5, '0');
end $$;

-- ───────────── customers and vehicles ─────────────
create table customers (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null default auth_financier_id() references financiers(id),
  customer_no text not null default next_code('customer', 'C'),
  full_name text not null check (length(trim(full_name)) > 0),
  mobile text not null check (mobile ~ '^[6-9][0-9]{9}$'),
  address text, district text, state text,
  status customer_status not null default 'active',
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, financier_id),
  unique (financier_id, customer_no)
);
create index customers_name_idx   on customers (financier_id, lower(full_name));
create index customers_mobile_idx on customers (financier_id, mobile);

create table vehicles (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null default auth_financier_id() references financiers(id),
  customer_id uuid not null,
  registration_number text not null check (registration_number = upper(registration_number) and registration_number !~ '\s'),
  make text, model text,
  manufacture_year int check (manufacture_year between 1950 and 2100),
  category vehicle_category not null default 'other',
  chassis_number text, engine_number text, registered_owner text,
  insurance_expiry date,
  hypothecation_details text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, financier_id),
  unique (financier_id, registration_number),
  foreign key (customer_id, financier_id) references customers (id, financier_id)
);
create index vehicles_customer_idx on vehicles (customer_id);

-- ───────────── loans ─────────────
create table loans (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null default auth_financier_id() references financiers(id),
  loan_no text not null default next_code('loan', 'L'),
  customer_id uuid not null,
  vehicle_id uuid not null,
  status loan_status not null default 'active',
  application_date date,
  approval_date date,
  disbursement_date date,
  principal_amount numeric(14,2) not null check (principal_amount > 0),
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, financier_id),
  unique (financier_id, loan_no),
  foreign key (customer_id, financier_id) references customers (id, financier_id),
  foreign key (vehicle_id, financier_id)  references vehicles (id, financier_id)
);
create index loans_customer_idx on loans (customer_id);
create index loans_status_idx   on loans (financier_id, status);

-- Terms are versioned so a restructure creates a new version instead of overwriting.
create table loan_terms (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null references financiers(id),
  loan_id uuid not null,
  version int not null default 1,
  is_current boolean not null default true,
  interest_rate_pa numeric(7,4) not null check (interest_rate_pa >= 0),
  interest_method interest_method not null,
  tenure_installments int not null check (tenure_installments > 0),
  frequency payment_frequency not null,
  installment_amount numeric(14,2) not null check (installment_amount > 0),
  first_due_date date not null,
  final_due_date date not null,
  processing_fee numeric(14,2) not null default 0 check (processing_fee >= 0),
  other_fees numeric(14,2) not null default 0 check (other_fees >= 0),
  notes text,
  created_at timestamptz not null default now(),
  unique (id, financier_id),
  unique (loan_id, version),
  check (final_due_date >= first_due_date),
  foreign key (loan_id, financier_id) references loans (id, financier_id)
);
create unique index loan_terms_one_current on loan_terms (loan_id) where is_current;

create table repayment_schedules (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null references financiers(id),
  loan_id uuid not null,
  loan_terms_id uuid not null,
  installment_no int not null check (installment_no > 0),
  due_date date not null,
  principal_due numeric(14,2) not null check (principal_due >= 0),
  interest_due  numeric(14,2) not null check (interest_due >= 0),
  fees_due      numeric(14,2) not null default 0 check (fees_due >= 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  unique (id, financier_id),
  unique (loan_terms_id, installment_no),
  foreign key (loan_id, financier_id) references loans (id, financier_id),
  foreign key (loan_terms_id, financier_id) references loan_terms (id, financier_id)
);
create index schedules_loan_idx on repayment_schedules (loan_id, installment_no);
create index schedules_due_idx  on repayment_schedules (financier_id, due_date) where is_active;

-- ───────────── documents (files live in private storage; only paths here) ─────────────
create table documents (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null default auth_financier_id() references financiers(id),
  customer_id uuid not null,
  vehicle_id uuid,
  loan_id uuid,
  category document_category not null,
  title text,
  status document_status not null default 'uploaded',
  expiry_date date,
  notes text,
  verified_by uuid,
  verified_at timestamptz,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, financier_id),
  foreign key (customer_id, financier_id) references customers (id, financier_id),
  foreign key (vehicle_id, financier_id)  references vehicles (id, financier_id),
  foreign key (loan_id, financier_id)     references loans (id, financier_id)
);
create index documents_customer_idx on documents (customer_id, category);
create index documents_expiry_idx   on documents (financier_id, expiry_date) where expiry_date is not null;

create table document_versions (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null default auth_financier_id() references financiers(id),
  document_id uuid not null,
  version_no int not null,
  storage_path text not null,
  file_name text,
  mime_type text not null check (mime_type in ('application/pdf','image/jpeg','image/png')),
  size_bytes bigint not null check (size_bytes > 0 and size_bytes <= 15728640),
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  uploaded_by uuid default auth.uid(),
  uploaded_at timestamptz not null default now(),
  unique (document_id, version_no),
  foreign key (document_id, financier_id) references documents (id, financier_id),
  check (storage_path like financier_id::text || '/%')
);
create index document_versions_hash_idx on document_versions (financier_id, sha256);

create table document_access_logs (
  id bigint generated always as identity primary key,
  financier_id uuid not null references financiers(id),
  document_id uuid not null,
  version_id uuid,
  actor_id uuid,
  action text not null check (action in ('preview','download')),
  created_at timestamptz not null default now()
);

-- ───────────── payments: append-only ledger ─────────────
create table payments (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null references financiers(id),
  loan_id uuid not null,
  kind payment_kind not null default 'receipt',
  amount numeric(14,2) not null,
  payment_date date not null,
  method payment_method not null,
  transaction_ref text,
  receipt_document_id uuid,
  reverses_payment_id uuid,
  reversal_reason text,
  notes text,
  recorded_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  unique (id, financier_id),
  foreign key (loan_id, financier_id) references loans (id, financier_id),
  foreign key (receipt_document_id, financier_id) references documents (id, financier_id),
  foreign key (reverses_payment_id, financier_id) references payments (id, financier_id),
  check (
    (kind = 'receipt'  and amount > 0 and reverses_payment_id is null) or
    (kind = 'reversal' and amount < 0 and reverses_payment_id is not null
                       and coalesce(length(trim(reversal_reason)), 0) > 0)
  )
);
create unique index payments_one_reversal on payments (reverses_payment_id) where kind = 'reversal';
create index payments_loan_idx on payments (loan_id);
create index payments_date_idx on payments (financier_id, payment_date);

create table payment_allocations (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null references financiers(id),
  payment_id uuid not null,
  schedule_id uuid not null,
  principal_amount numeric(14,2) not null default 0,
  interest_amount  numeric(14,2) not null default 0,
  fees_amount      numeric(14,2) not null default 0,
  created_at timestamptz not null default now(),
  foreign key (payment_id, financier_id)  references payments (id, financier_id),
  foreign key (schedule_id, financier_id) references repayment_schedules (id, financier_id),
  check (principal_amount <> 0 or interest_amount <> 0 or fees_amount <> 0)
);
create index allocations_schedule_idx on payment_allocations (schedule_id);
create index allocations_payment_idx  on payment_allocations (payment_id);

-- ───────────── settings, audit ─────────────
create table business_settings (
  financier_id uuid not null references financiers(id),
  key text not null,
  value jsonb not null,
  updated_at timestamptz not null default now(),
  primary key (financier_id, key)
);

create table audit_logs (
  id bigint generated always as identity primary key,
  financier_id uuid,
  actor_id uuid,
  action text not null,
  table_name text not null,
  record_id uuid,
  old_data jsonb,
  new_data jsonb,
  created_at timestamptz not null default now()
);
create index audit_logs_record_idx on audit_logs (financier_id, table_name, record_id);

create function audit_row() returns trigger language plpgsql security definer set search_path = public as $$
declare j jsonb := to_jsonb(case when tg_op = 'DELETE' then old else new end);
begin
  insert into audit_logs (financier_id, actor_id, action, table_name, record_id, old_data, new_data)
  values ((j->>'financier_id')::uuid, auth.uid(), tg_op, tg_table_name, (j->>'id')::uuid,
          case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,
          case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end);
  return null;
end $$;

create function forbid_mutation() returns trigger language plpgsql as $$
begin
  raise exception '% on % is not allowed: this table is append-only', tg_op, tg_table_name using errcode = '42501';
end $$;

do $$
declare t text;
begin
  foreach t in array array['customers','vehicles','loans','loan_terms','repayment_schedules','documents',
                           'document_versions','payments','payment_allocations','profiles','business_settings']
  loop
    execute format('create trigger trg_audit after insert or update or delete on %I for each row execute function audit_row()', t);
  end loop;
  foreach t in array array['payments','payment_allocations','audit_logs','document_versions','document_access_logs']
  loop
    execute format('create trigger trg_append_only before update or delete on %I for each row execute function forbid_mutation()', t);
  end loop;
end $$;

create function touch_updated_at() returns trigger language plpgsql as
$$ begin new.updated_at := now(); return new; end $$;
create trigger trg_touch before update on customers for each row execute function touch_updated_at();
create trigger trg_touch before update on vehicles  for each row execute function touch_updated_at();
create trigger trg_touch before update on loans     for each row execute function touch_updated_at();

create function document_version_no() returns trigger language plpgsql as $$
begin
  if new.version_no is null then
    select coalesce(max(version_no), 0) + 1 into new.version_no from document_versions where document_id = new.document_id;
  end if;
  return new;
end $$;
create trigger trg_version_no before insert on document_versions for each row execute function document_version_no();
-- version_no is NOT NULL but filled by the trigger above, so it is declared without default.

create function documents_guard() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.status in ('verified','rejected') then
      raise exception 'new documents cannot start as %', new.status using errcode = '42501';
    end if;
  else
    if new.status is distinct from old.status and new.status in ('verified','rejected') then
      if not has_permission('documents.verify') then
        raise exception 'permission denied: documents.verify' using errcode = '42501';
      end if;
      new.verified_by := auth.uid(); new.verified_at := now();
    elsif new.status is distinct from old.status and old.status = 'verified' then
      new.verified_by := null; new.verified_at := null;
    end if;
    new.updated_at := now();
  end if;
  return new;
end $$;
create trigger trg_documents_guard before insert or update on documents for each row execute function documents_guard();

-- ═══════════ 0002_views_functions_rls.sql ═══════════
-- Milestone 1 part 2: derived views, financial RPCs, row-level security, grants.

-- ───────────── derived views (security_invoker: RLS of the caller applies) ─────────────
create view v_schedule_status with (security_invoker = true) as
select x.*,
  case
    when x.total_outstanding = 0           then 'paid'
    when x.due_date < today_ist()          then 'overdue'
    when x.paid_total > 0                  then 'partially_paid'
    when x.due_date = today_ist()          then 'due'
    else 'upcoming'
  end as status
from (
  select s.id as schedule_id, s.financier_id, s.loan_id, s.installment_no, s.due_date,
         s.principal_due, s.interest_due, s.fees_due,
         s.principal_due + s.interest_due + s.fees_due as amount_due,
         coalesce(a.p, 0) as paid_principal, coalesce(a.i, 0) as paid_interest, coalesce(a.f, 0) as paid_fees,
         coalesce(a.p, 0) + coalesce(a.i, 0) + coalesce(a.f, 0) as paid_total,
         s.principal_due - coalesce(a.p, 0) as principal_outstanding,
         s.interest_due  - coalesce(a.i, 0) as interest_outstanding,
         s.fees_due      - coalesce(a.f, 0) as fees_outstanding,
         (s.principal_due + s.interest_due + s.fees_due) - (coalesce(a.p,0) + coalesce(a.i,0) + coalesce(a.f,0)) as total_outstanding
  from repayment_schedules s
  left join (select schedule_id, sum(principal_amount) p, sum(interest_amount) i, sum(fees_amount) f
             from payment_allocations group by schedule_id) a on a.schedule_id = s.id
  where s.is_active
) x;

-- "interest_outstanding" = scheduled interest on instalments not yet paid (not accrued-to-date interest).
create view v_loan_outstanding with (security_invoker = true) as
select l.id as loan_id, l.financier_id, l.loan_no, l.status, l.customer_id, l.vehicle_id, l.principal_amount,
       coalesce(sum(v.principal_outstanding), 0) as principal_outstanding,
       coalesce(sum(v.interest_outstanding), 0)  as interest_outstanding,
       coalesce(sum(v.fees_outstanding), 0)      as fees_outstanding,
       coalesce(sum(v.total_outstanding), 0)     as total_receivable,
       coalesce(sum(v.total_outstanding) filter (where v.due_date < today_ist()), 0) as overdue_amount,
       count(*) filter (where v.total_outstanding > 0 and v.due_date < today_ist())  as overdue_installments,
       min(v.due_date) filter (where v.total_outstanding > 0) as next_due_date
from loans l left join v_schedule_status v on v.loan_id = l.id
group by l.id;

create view v_documents with (security_invoker = true) as
select d.*,
       case when d.expiry_date is not null and d.expiry_date < today_ist() then 'expired'::document_status else d.status end as effective_status,
       d.expiry_date - today_ist() as days_to_expiry,
       (select max(version_no) from document_versions dv where dv.document_id = d.id) as latest_version_no
from documents d;

create view v_dashboard_summary with (security_invoker = true) as
select
  (select count(*) from customers)                                          as total_customers,
  (select count(*) from loans where status in ('active','overdue'))         as active_loans,
  (select count(*) from loans where disbursement_date is not null)          as loans_disbursed,
  (select coalesce(sum(principal_amount),0) from loans where disbursement_date is not null) as amount_disbursed,
  (select coalesce(sum(amount),0) from payments
     where date_trunc('month', payment_date) = date_trunc('month', today_ist())) as collections_this_month,
  (select coalesce(sum(principal_outstanding),0) from v_loan_outstanding where status in ('active','overdue')) as principal_outstanding,
  (select coalesce(sum(overdue_amount),0) from v_loan_outstanding where status in ('active','overdue'))        as overdue_amount,
  (select count(*) from v_schedule_status where status = 'paid')            as paid_installments,
  (select count(*) from v_schedule_status where total_outstanding > 0)      as unpaid_installments,
  (select count(*) from v_schedule_status where status = 'overdue')         as overdue_installments,
  (select count(*) from vehicles where insurance_expiry < today_ist())      as expired_insurance,
  (select count(*) from vehicles where insurance_expiry between today_ist() and today_ist() + 30) as insurance_expiring_30d;

-- ───────────── financial RPCs (the only write path for the ledger) ─────────────
create function refresh_loan_status(p_loan_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare o record;
begin
  select * into o from v_loan_outstanding where loan_id = p_loan_id;
  update loans set status = (case when o.total_receivable = 0 then 'closed'
                                  when o.overdue_amount > 0   then 'overdue'
                                  else 'active' end)::loan_status
  where id = p_loan_id and status in ('disbursed','active','overdue','closed');
end $$;

-- For a daily scheduled job (service role / pg_cron): overdue status changes with the calendar.
create function refresh_all_loan_statuses() returns int
language plpgsql security definer set search_path = public as $$
declare r record; n int := 0;
begin
  for r in select id from loans where status in ('disbursed','active','overdue') loop
    perform refresh_loan_status(r.id); n := n + 1;
  end loop;
  return n;
end $$;

create function create_loan(
  p_customer_id uuid, p_vehicle_id uuid, p_principal numeric,
  p_application_date date, p_approval_date date, p_disbursement_date date,
  p_terms jsonb, p_schedule jsonb
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_fin uuid := auth_financier_id(); v_loan uuid; v_terms uuid;
  v_n int; v_sum numeric; v_cnt int; v_first date; v_last date; v_fees numeric;
begin
  if not has_permission('loans.write') then raise exception 'permission denied: loans.write' using errcode = '42501'; end if;
  if p_disbursement_date is null then raise exception 'disbursement_date is required for a loan record'; end if;
  if not exists (select 1 from vehicles where id = p_vehicle_id and customer_id = p_customer_id and financier_id = v_fin) then
    raise exception 'vehicle does not belong to this customer';
  end if;

  v_n := (p_terms->>'tenure_installments')::int;
  select count(*), coalesce(sum(principal_due),0), min(due_date), max(due_date), count(distinct installment_no)
    into v_cnt, v_sum, v_first, v_last, v_n
  from jsonb_to_recordset(p_schedule) as t(installment_no int, due_date date, principal_due numeric, interest_due numeric, fees_due numeric);
  if v_cnt <> (p_terms->>'tenure_installments')::int or v_n <> v_cnt then raise exception 'schedule must have exactly tenure_installments distinct rows'; end if;
  if v_sum <> p_principal then raise exception 'schedule principal (%) must equal loan principal (%)', v_sum, p_principal; end if;
  if exists (select 1 from jsonb_to_recordset(p_schedule) as t(installment_no int, due_date date)
             where installment_no not between 1 and v_cnt) then raise exception 'installment_no must run 1..n'; end if;
  if exists (select 1 from (select installment_no, due_date, lag(due_date) over (order by installment_no) pd
                            from jsonb_to_recordset(p_schedule) as t(installment_no int, due_date date)) q
             where pd is not null and due_date <= pd) then raise exception 'due dates must be strictly increasing'; end if;

  insert into loans (financier_id, customer_id, vehicle_id, status, application_date, approval_date, disbursement_date, principal_amount)
  values (v_fin, p_customer_id, p_vehicle_id, 'active', p_application_date, p_approval_date, p_disbursement_date, p_principal)
  returning id into v_loan;

  insert into loan_terms (financier_id, loan_id, interest_rate_pa, interest_method, tenure_installments, frequency,
                          installment_amount, first_due_date, final_due_date, processing_fee, other_fees, notes)
  values (v_fin, v_loan, (p_terms->>'interest_rate_pa')::numeric, (p_terms->>'interest_method')::interest_method,
          (p_terms->>'tenure_installments')::int, (p_terms->>'frequency')::payment_frequency,
          (p_terms->>'installment_amount')::numeric, v_first, v_last,
          coalesce((p_terms->>'processing_fee')::numeric, 0), coalesce((p_terms->>'other_fees')::numeric, 0), p_terms->>'notes')
  returning id into v_terms;

  insert into repayment_schedules (financier_id, loan_id, loan_terms_id, installment_no, due_date, principal_due, interest_due, fees_due)
  select v_fin, v_loan, v_terms, installment_no, due_date, principal_due, interest_due, coalesce(fees_due, 0)
  from jsonb_to_recordset(p_schedule) as t(installment_no int, due_date date, principal_due numeric, interest_due numeric, fees_due numeric);

  perform refresh_loan_status(v_loan);
  return v_loan;
end $$;

-- Allocation order: oldest instalment first; within an instalment fees → interest → principal.
-- Advance payments simply flow into the next unpaid instalments. Overpayment is rejected.
create function record_payment(
  p_loan_id uuid, p_amount numeric, p_payment_date date, p_method payment_method,
  p_reference text default null, p_notes text default null, p_receipt_document_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_fin uuid := auth_financier_id(); v_loan loans%rowtype; v_pay uuid;
  v_rem numeric(14,2) := p_amount; r record; f numeric; i numeric; p numeric;
begin
  if not has_permission('payments.record') then raise exception 'permission denied: payments.record' using errcode = '42501'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'amount must be positive'; end if;
  if p_amount <> round(p_amount, 2) then raise exception 'amount cannot have more than 2 decimals'; end if;
  if p_payment_date > today_ist() then raise exception 'payment_date cannot be in the future'; end if;
  select * into v_loan from loans where id = p_loan_id and financier_id = v_fin for update;
  if not found then raise exception 'loan not found'; end if;
  if v_loan.status not in ('disbursed','active','overdue') then raise exception 'loan status % does not accept payments', v_loan.status; end if;

  insert into payments (financier_id, loan_id, kind, amount, payment_date, method, transaction_ref, notes, receipt_document_id)
  values (v_fin, p_loan_id, 'receipt', p_amount, p_payment_date, p_method, p_reference, p_notes, p_receipt_document_id)
  returning id into v_pay;

  for r in select * from v_schedule_status where loan_id = p_loan_id and total_outstanding > 0 order by installment_no loop
    exit when v_rem <= 0;
    f := least(v_rem, r.fees_outstanding);     v_rem := v_rem - f;
    i := least(v_rem, r.interest_outstanding); v_rem := v_rem - i;
    p := least(v_rem, r.principal_outstanding); v_rem := v_rem - p;
    if f + i + p > 0 then
      insert into payment_allocations (financier_id, payment_id, schedule_id, principal_amount, interest_amount, fees_amount)
      values (v_fin, v_pay, r.schedule_id, p, i, f);
    end if;
  end loop;
  if v_rem > 0 then raise exception 'payment exceeds total receivable by %', v_rem; end if;

  perform refresh_loan_status(p_loan_id);
  return v_pay;
end $$;

-- A reversal is a new negative ledger entry mirroring the original allocations. Nothing is edited or deleted.
create function reverse_payment(p_payment_id uuid, p_reason text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_fin uuid := auth_financier_id(); v_pay payments%rowtype; v_new uuid;
begin
  if not has_permission('payments.reverse') then raise exception 'permission denied: payments.reverse' using errcode = '42501'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'a reason is required'; end if;
  select * into v_pay from payments where id = p_payment_id and financier_id = v_fin;
  if not found then raise exception 'payment not found'; end if;
  if v_pay.kind <> 'receipt' then raise exception 'only receipts can be reversed'; end if;
  perform 1 from loans where id = v_pay.loan_id for update;
  if exists (select 1 from payments where reverses_payment_id = p_payment_id) then raise exception 'payment already reversed'; end if;

  insert into payments (financier_id, loan_id, kind, amount, payment_date, method, transaction_ref, reverses_payment_id, reversal_reason)
  values (v_fin, v_pay.loan_id, 'reversal', -v_pay.amount, today_ist(), v_pay.method, v_pay.transaction_ref, p_payment_id, p_reason)
  returning id into v_new;
  insert into payment_allocations (financier_id, payment_id, schedule_id, principal_amount, interest_amount, fees_amount)
  select v_fin, v_new, schedule_id, -principal_amount, -interest_amount, -fees_amount from payment_allocations where payment_id = p_payment_id;

  perform refresh_loan_status(v_pay.loan_id);
  return v_new;
end $$;

create function log_document_access(p_document_id uuid, p_version_id uuid, p_action text) returns void
language plpgsql security definer set search_path = public as $$
declare v_fin uuid := auth_financier_id();
begin
  if v_fin is null or not exists (select 1 from documents where id = p_document_id and financier_id = v_fin) then
    raise exception 'document not found' using errcode = '42501';
  end if;
  insert into document_access_logs (financier_id, document_id, version_id, actor_id, action)
  values (v_fin, p_document_id, p_version_id, auth.uid(), p_action);
end $$;

-- ───────────── row-level security ─────────────
do $$
declare t text;
begin
  foreach t in array array['financiers','profiles','id_counters','customers','vehicles','loans','loan_terms','repayment_schedules',
                           'documents','document_versions','document_access_logs','payments','payment_allocations','business_settings','audit_logs']
  loop execute format('alter table %I enable row level security', t); end loop;
end $$;

create policy financiers_select on financiers for select to authenticated using (id = auth_financier_id());

create policy profiles_select on profiles for select to authenticated using (id = auth.uid() or financier_id = auth_financier_id());
create policy profiles_update on profiles for update to authenticated
  using (financier_id = auth_financier_id() and auth_role() = 'owner' and role = 'employee')
  with check (financier_id = auth_financier_id() and role = 'employee');

-- Read access: any active member of the tenant. Write access: per permission.
do $$
declare t text;
begin
  foreach t in array array['customers','vehicles','loans','loan_terms','repayment_schedules','documents','document_versions','payments','payment_allocations','business_settings']
  loop execute format('create policy %I on %I for select to authenticated using (financier_id = auth_financier_id())', t || '_select', t); end loop;
end $$;

create policy customers_insert on customers for insert to authenticated with check (financier_id = auth_financier_id() and has_permission('customers.write'));
create policy customers_update on customers for update to authenticated using (financier_id = auth_financier_id() and has_permission('customers.write')) with check (financier_id = auth_financier_id());
create policy vehicles_insert  on vehicles  for insert to authenticated with check (financier_id = auth_financier_id() and has_permission('vehicles.write'));
create policy vehicles_update  on vehicles  for update to authenticated using (financier_id = auth_financier_id() and has_permission('vehicles.write')) with check (financier_id = auth_financier_id());
create policy documents_insert on documents for insert to authenticated with check (financier_id = auth_financier_id() and has_permission('documents.upload'));
create policy documents_update on documents for update to authenticated using (financier_id = auth_financier_id() and has_permission('documents.upload')) with check (financier_id = auth_financier_id());
create policy docversions_insert on document_versions for insert to authenticated with check (financier_id = auth_financier_id() and has_permission('documents.upload'));
create policy settings_insert on business_settings for insert to authenticated with check (financier_id = auth_financier_id() and auth_role() = 'owner');
create policy settings_update on business_settings for update to authenticated using (financier_id = auth_financier_id() and auth_role() = 'owner') with check (financier_id = auth_financier_id());
create policy audit_select on audit_logs for select to authenticated using (financier_id = auth_financier_id() and auth_role() = 'owner');
create policy access_logs_select on document_access_logs for select to authenticated using (financier_id = auth_financier_id() and auth_role() = 'owner');
-- No policies on payments/allocations/loans/terms/schedules for insert/update/delete: those go through the RPCs above.
-- No delete policy exists anywhere: records are never hard-deleted by users.

-- ───────────── grants (least privilege) ─────────────
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke execute on all functions in schema public from public;

grant usage on schema public to authenticated;
grant select on financiers, profiles, customers, vehicles, loans, loan_terms, repayment_schedules, documents, document_versions,
                document_access_logs, payments, payment_allocations, business_settings, audit_logs,
                v_schedule_status, v_loan_outstanding, v_documents, v_dashboard_summary to authenticated;
grant insert, update on customers, vehicles, documents, business_settings to authenticated;
grant insert on document_versions to authenticated;
grant update (full_name, phone, permissions, is_active) on profiles to authenticated;
grant execute on function auth_financier_id(), auth_role(), has_permission(text), next_code(text, text), today_ist(),
  create_loan(uuid, uuid, numeric, date, date, date, jsonb, jsonb),
  record_payment(uuid, numeric, date, payment_method, text, text, uuid),
  reverse_payment(uuid, text), log_document_access(uuid, uuid, text) to authenticated;
-- refresh_loan_status / refresh_all_loan_statuses stay service-role only (daily job).

-- ═══════════ 0003_storage_private_bucket.sql ═══════════
-- Private document bucket. Skipped automatically where Supabase Storage is not installed (e.g. plain Postgres tests).
-- Object path convention: <financier_id>/<customer_id>/<document_id>/<version_no>-<filename>
do $$
begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('documents', 'documents', false, 15728640, array['application/pdf','image/jpeg','image/png'])
    on conflict (id) do nothing;

    execute $p$ create policy documents_read on storage.objects for select to authenticated
      using (bucket_id = 'documents' and (storage.foldername(name))[1] = public.auth_financier_id()::text) $p$;
    execute $p$ create policy documents_write on storage.objects for insert to authenticated
      with check (bucket_id = 'documents' and (storage.foldername(name))[1] = public.auth_financier_id()::text
                  and public.has_permission('documents.upload')) $p$;
    -- No update/delete policies: stored files are immutable; a replacement is a new version path.
  end if;
end $$;

-- ═══════════ 0004_daily_status_refresh.sql ═══════════
-- Loans turn "overdue" with the calendar, not with a user action, so refresh statuses every day at 00:30 IST (19:00 UTC).
-- The app also shows overdue immediately wherever money is past due; this keeps stored statuses and reports in step.
-- Skipped silently if pg_cron is not available. On Supabase: Database → Extensions → enable pg_cron, then re-run this file.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.unschedule(jobid) from cron.job where jobname = 'refresh-loan-statuses';
    perform cron.schedule('refresh-loan-statuses', '0 19 * * *', 'select public.refresh_all_loan_statuses()');
  else
    raise notice 'pg_cron not available; schedule select refresh_all_loan_statuses() daily another way';
  end if;
exception when others then
  raise notice 'could not schedule daily refresh: %', sqlerrm;
end $$;

-- ═══════════ 0005_documents.sql ═══════════
-- Milestone 5: atomic document registration, insurance-expiry sync, "to verify" count on the dashboard.

-- The browser uploads the file to private storage, then calls this once. Document row + version row are created together
-- (or not at all), the path must sit inside this tenant/customer/document folder, and related ids must belong to the customer.
create function register_document_upload(
  p_document_id uuid, p_is_new boolean, p_customer_id uuid, p_vehicle_id uuid, p_loan_id uuid,
  p_category document_category, p_title text, p_expiry date, p_storage_path text, p_file_name text,
  p_mime text, p_size bigint, p_sha256 text
) returns int language plpgsql security definer set search_path = public as $$
declare v_fin uuid := auth_financier_id(); v_ver int; v_prefix text;
begin
  if not has_permission('documents.upload') then raise exception 'permission denied: documents.upload' using errcode = '42501'; end if;
  v_prefix := v_fin::text || '/' || p_customer_id::text || '/' || p_document_id::text || '/';
  if left(p_storage_path, length(v_prefix)) <> v_prefix then raise exception 'storage path does not match document'; end if;
  if not exists (select 1 from customers where id = p_customer_id and financier_id = v_fin) then raise exception 'customer not found'; end if;
  if p_vehicle_id is not null and not exists (select 1 from vehicles where id = p_vehicle_id and customer_id = p_customer_id and financier_id = v_fin) then
    raise exception 'vehicle does not belong to this customer'; end if;
  if p_loan_id is not null and not exists (select 1 from loans where id = p_loan_id and customer_id = p_customer_id and financier_id = v_fin) then
    raise exception 'loan does not belong to this customer'; end if;

  if p_is_new then
    insert into documents (id, financier_id, customer_id, vehicle_id, loan_id, category, title, expiry_date)
    values (p_document_id, v_fin, p_customer_id, p_vehicle_id, p_loan_id, p_category, nullif(trim(p_title), ''), p_expiry);
  else
    perform 1 from documents where id = p_document_id and financier_id = v_fin and customer_id = p_customer_id for update;
    if not found then raise exception 'document not found'; end if;
    -- a replacement file must be reviewed again
    update documents set status = (case when status in ('verified','rejected','needs_attention','expired') then 'uploaded' else status end)::document_status,
                         expiry_date = coalesce(p_expiry, expiry_date)
    where id = p_document_id;
  end if;

  select coalesce(max(version_no), 0) + 1 into v_ver from document_versions where document_id = p_document_id;
  insert into document_versions (financier_id, document_id, version_no, storage_path, file_name, mime_type, size_bytes, sha256)
  values (v_fin, p_document_id, v_ver, p_storage_path, p_file_name, p_mime, p_size, p_sha256);
  return v_ver;
end $$;

-- Vehicle insurance date follows the latest non-rejected insurance document that has an expiry date.
create function sync_vehicle_insurance() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.category = 'insurance' and new.vehicle_id is not null then
    update vehicles set insurance_expiry = coalesce((select max(expiry_date) from documents
        where vehicle_id = new.vehicle_id and category = 'insurance' and status <> 'rejected' and expiry_date is not null), insurance_expiry)
    where id = new.vehicle_id;
  end if;
  return null;
end $$;
create trigger trg_sync_insurance after insert or update of expiry_date, status, category, vehicle_id on documents
  for each row execute function sync_vehicle_insurance();

create or replace view v_dashboard_summary with (security_invoker = true) as
select
  (select count(*) from customers)                                          as total_customers,
  (select count(*) from loans where status in ('active','overdue'))         as active_loans,
  (select count(*) from loans where disbursement_date is not null)          as loans_disbursed,
  (select coalesce(sum(principal_amount),0) from loans where disbursement_date is not null) as amount_disbursed,
  (select coalesce(sum(amount),0) from payments
     where date_trunc('month', payment_date) = date_trunc('month', today_ist())) as collections_this_month,
  (select coalesce(sum(principal_outstanding),0) from v_loan_outstanding where status in ('active','overdue')) as principal_outstanding,
  (select coalesce(sum(overdue_amount),0) from v_loan_outstanding where status in ('active','overdue'))        as overdue_amount,
  (select count(*) from v_schedule_status where status = 'paid')            as paid_installments,
  (select count(*) from v_schedule_status where total_outstanding > 0)      as unpaid_installments,
  (select count(*) from v_schedule_status where status = 'overdue')         as overdue_installments,
  (select count(*) from vehicles where insurance_expiry < today_ist())      as expired_insurance,
  (select count(*) from vehicles where insurance_expiry between today_ist() and today_ist() + 30) as insurance_expiring_30d,
  (select count(*) from documents where status in ('uploaded','pending_review')) as documents_to_verify;

grant execute on function register_document_upload(uuid, boolean, uuid, uuid, uuid, document_category, text, date, text, text, text, bigint, text) to authenticated;
grant select on v_dashboard_summary to authenticated;

-- ═══════════ 0006_reports.sql ═══════════
-- Milestone 6: reporting queries. All are SECURITY INVOKER, so row-level security limits them to the caller's business.

-- Overdue as it stood at the START of p_date: instalments due before p_date, minus payments dated before p_date.
create function overdue_as_of(p_date date) returns numeric
language sql stable security invoker set search_path = public as $$
  select coalesce(sum(greatest(s.principal_due + s.interest_due + s.fees_due - coalesce(a.paid, 0), 0)), 0)
  from repayment_schedules s
  left join lateral (
    select sum(al.principal_amount + al.interest_amount + al.fees_amount) as paid
    from payment_allocations al join payments p on p.id = al.payment_id
    where al.schedule_id = s.id and p.payment_date < p_date
  ) a on true
  where s.is_active and s.due_date < p_date
$$;

-- One row per month for the last p_months (max 36), oldest first. overdue_amount is the position at the end of that month
-- (for the current month: as of the start of today). Collections are net of reversals.
create function report_monthly(p_months int default 12) returns table (
  month date, disbursed_count bigint, disbursed_amount numeric, collected numeric, overdue_amount numeric
) language sql stable security invoker set search_path = public as $$
  with m as (
    select (date_trunc('month', today_ist()) - make_interval(months => n))::date as month
    from generate_series(0, greatest(least(p_months, 36), 1) - 1) n
  )
  select m.month,
    (select count(*) from loans l where l.disbursement_date >= m.month and l.disbursement_date < (m.month + interval '1 month')::date),
    (select coalesce(sum(l.principal_amount), 0) from loans l where l.disbursement_date >= m.month and l.disbursement_date < (m.month + interval '1 month')::date),
    (select coalesce(sum(p.amount), 0) from payments p where p.payment_date >= m.month and p.payment_date < (m.month + interval '1 month')::date),
    overdue_as_of(least((m.month + interval '1 month')::date, today_ist()))
  from m order by m.month
$$;

create function report_daily_collections(p_from date, p_to date) returns table (day date, receipts bigint, collected numeric)
language sql stable security invoker set search_path = public as $$
  select p.payment_date, count(*) filter (where p.kind = 'receipt'), sum(p.amount)
  from payments p where p.payment_date between p_from and p_to
  group by p.payment_date order by p.payment_date
$$;

create view v_category_distribution with (security_invoker = true) as
select v.category, count(*) as loans_count, coalesce(sum(l.principal_amount), 0) as disbursed_amount
from loans l join vehicles v on v.id = l.vehicle_id
where l.disbursement_date is not null
group by v.category;

create view v_loan_status_distribution with (security_invoker = true) as
select (case when status = 'active' and overdue_amount > 0 then 'overdue' else status::text end) as status, count(*) as loans_count
from v_loan_outstanding group by 1;

-- Tighten function access: nothing is callable by anonymous or public roles unless listed here.
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function auth_financier_id(), auth_role(), has_permission(text), next_code(text, text), today_ist(),
  create_loan(uuid, uuid, numeric, date, date, date, jsonb, jsonb),
  record_payment(uuid, numeric, date, payment_method, text, text, uuid),
  reverse_payment(uuid, text), log_document_access(uuid, uuid, text),
  register_document_upload(uuid, boolean, uuid, uuid, uuid, document_category, text, date, text, text, text, bigint, text),
  overdue_as_of(date), report_monthly(int), report_daily_collections(date, date) to authenticated;
grant select on v_category_distribution, v_loan_status_distribution to authenticated;

-- ═══════════ 0007_service_role_grants.sql ═══════════
-- Newer Supabase projects may not give the server-side "service_role" access to tables created through the SQL Editor.
-- The service role is the trusted server key (never used in the browser); it needs full access for admin tasks such as
-- creating the first owner and employee logins. Safe to run more than once. Browser/anonymous roles are NOT changed here.
grant usage on schema public to service_role;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on sequences to service_role;
alter default privileges in schema public grant execute on functions to service_role;

-- ═══════════ 0008_essentials.sql ═══════════
-- Milestone 7: required-documents rules, missing-document detection, follow-up tasks, live alerts.

-- ───────────── required documents (owner-configurable per business) ─────────────
create table required_document_rules (
  financier_id uuid not null default auth_financier_id() references financiers(id),
  category document_category not null,
  created_at timestamptz not null default now(),
  primary key (financier_id, category)
);

create function seed_default_required_documents() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into required_document_rules (financier_id, category)
  select new.id, c from unnest(array['rc','insurance','kyc','address_proof','loan_agreement']::document_category[]) c on conflict do nothing;
  return new;
end $$;
create trigger trg_seed_rules after insert on financiers for each row execute function seed_default_required_documents();
insert into required_document_rules (financier_id, category)
select f.id, c from financiers f cross join unnest(array['rc','insurance','kyc','address_proof','loan_agreement']::document_category[]) c on conflict do nothing;

-- A requirement is met by any non-rejected document of that type for the customer that is not tied to a different loan or vehicle.
-- (An expired document still counts as present; expiry has its own alert.)
create view v_loan_missing_documents with (security_invoker = true) as
select l.id as loan_id, l.financier_id, l.loan_no, l.customer_id, l.vehicle_id, r.category
from loans l join required_document_rules r on r.financier_id = l.financier_id
where l.status in ('active', 'overdue') and not exists (
  select 1 from documents d
  where d.financier_id = l.financier_id and d.customer_id = l.customer_id and d.category = r.category and d.status <> 'rejected'
    and (d.loan_id is null or d.loan_id = l.id) and (d.vehicle_id is null or d.vehicle_id = l.vehicle_id));

create view v_loan_file_status with (security_invoker = true) as
select l.id as loan_id, l.financier_id, l.loan_no, l.customer_id, l.vehicle_id,
  (select count(*) from required_document_rules r where r.financier_id = l.financier_id) as required_count,
  (select count(*) from v_loan_missing_documents m where m.loan_id = l.id) as missing_count
from loans l where l.status in ('active', 'overdue');

-- ───────────── follow-up tasks ─────────────
create type task_status as enum ('open', 'done', 'cancelled');
create table follow_up_tasks (
  id uuid primary key default gen_random_uuid(),
  financier_id uuid not null default auth_financier_id() references financiers(id),
  customer_id uuid,
  loan_id uuid,
  title text not null check (length(trim(title)) between 2 and 200),
  notes text,
  due_date date not null,
  assigned_to uuid references profiles(id),
  status task_status not null default 'open',
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  completed_by uuid,
  completed_at timestamptz,
  unique (id, financier_id),
  foreign key (customer_id, financier_id) references customers (id, financier_id),
  foreign key (loan_id, financier_id) references loans (id, financier_id)
);
create index tasks_open_idx on follow_up_tasks (financier_id, due_date) where status = 'open';

create function task_guard() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.assigned_to is not null and not exists (select 1 from profiles where id = new.assigned_to and financier_id = new.financier_id) then
    raise exception 'assigned person is not part of this business' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    new.status := 'open'; new.completed_by := null; new.completed_at := null;
  else
    if new.financier_id <> old.financier_id or new.customer_id is distinct from old.customer_id or new.loan_id is distinct from old.loan_id then
      raise exception 'task links cannot be changed';
    end if;
    if new.status <> old.status then
      if new.status = 'open' then new.completed_by := null; new.completed_at := null;
      else new.completed_by := auth.uid(); new.completed_at := now(); end if;
    end if;
  end if;
  return new;
end $$;
create trigger trg_task_guard before insert or update on follow_up_tasks for each row execute function task_guard();
create trigger trg_audit after insert or update or delete on follow_up_tasks for each row execute function audit_row();

create function audit_row_rules() returns trigger language plpgsql security definer set search_path = public as $$
declare r required_document_rules;
begin
  r := case when tg_op = 'DELETE' then old else new end;
  insert into audit_logs (financier_id, actor_id, action, table_name, record_id, old_data, new_data)
  values (r.financier_id, auth.uid(), tg_op, tg_table_name, null,
          case when tg_op = 'DELETE' then to_jsonb(old) end, case when tg_op = 'INSERT' then to_jsonb(new) end);
  return null;
end $$;
create trigger trg_audit after insert or update or delete on required_document_rules for each row execute function audit_row_rules();

-- ───────────── live alerts (computed from current data; nothing to go stale) ─────────────
create view v_alerts with (security_invoker = true) as
-- overdue loans
select 'overdue_loan'::text as kind, 'high'::text as severity, o.financier_id, o.customer_id, c.full_name as customer_name, o.loan_id, o.loan_no, o.vehicle_id,
       v.registration_number, null::uuid as document_id, null::uuid as task_id, o.next_due_date as due_date, o.overdue_amount as amount,
       o.overdue_installments::bigint as count_value, null::text as label
from v_loan_outstanding o join customers c on c.id = o.customer_id join vehicles v on v.id = o.vehicle_id
where o.overdue_amount > 0 and o.status in ('active', 'overdue')
union all
-- instalments due in the next 7 days
select 'upcoming_installment', case when s.due_date = today_ist() then 'medium' else 'low' end, s.financier_id, l.customer_id, c.full_name, l.id, l.loan_no, l.vehicle_id,
       v.registration_number, null, null, s.due_date, s.total_outstanding, 1::bigint, null
from v_schedule_status s join loans l on l.id = s.loan_id join customers c on c.id = l.customer_id join vehicles v on v.id = l.vehicle_id
where s.total_outstanding > 0 and s.due_date between today_ist() and today_ist() + 7 and l.status in ('active', 'overdue')
union all
-- insurance of vehicles that have an open loan
select case when v.insurance_expiry < today_ist() then 'insurance_expired' else 'insurance_expiring' end,
       case when v.insurance_expiry < today_ist() then 'high' else 'medium' end, v.financier_id, v.customer_id, c.full_name, ln.id, ln.loan_no, v.id,
       v.registration_number, null, null, v.insurance_expiry, null, 1::bigint, null
from vehicles v join customers c on c.id = v.customer_id
cross join lateral (select l.id, l.loan_no from loans l where l.vehicle_id = v.id and l.status in ('active', 'overdue') order by l.loan_no limit 1) ln
where v.insurance_expiry <= today_ist() + 30
union all
-- other documents with an expiry date (insurance linked to a vehicle is covered above)
select case when d.expiry_date < today_ist() then 'document_expired' else 'document_expiring' end,
       case when d.expiry_date < today_ist() then 'high' else 'medium' end, d.financier_id, d.customer_id, c.full_name, null, null, d.vehicle_id,
       null, d.id, null, d.expiry_date, null, 1::bigint, d.category::text
from documents d join customers c on c.id = d.customer_id
where d.expiry_date <= today_ist() + 30 and d.status <> 'rejected' and not (d.category = 'insurance' and d.vehicle_id is not null)
union all
-- loan files missing required documents
select 'missing_documents', 'medium', f.financier_id, f.customer_id, c.full_name, f.loan_id, f.loan_no, f.vehicle_id, null, null, null, null, null, f.missing_count, null
from v_loan_file_status f join customers c on c.id = f.customer_id where f.missing_count > 0
union all
-- documents waiting for a staff check (one row per business)
select 'documents_to_verify', 'low', financier_id, null, null, null, null, null, null, null, null, null, null, count(*), null
from documents where status in ('uploaded', 'pending_review') group by financier_id
union all
-- follow-ups that are due
select 'follow_up', case when t.due_date < today_ist() then 'high' else 'medium' end, t.financier_id, t.customer_id, c.full_name, t.loan_id, l.loan_no, null, null, null,
       t.id, t.due_date, null, 1::bigint, t.title
from follow_up_tasks t left join customers c on c.id = t.customer_id left join loans l on l.id = t.loan_id
where t.status = 'open' and t.due_date <= today_ist();

-- dashboard gets two more figures (columns appended; existing ones unchanged)
create or replace view v_dashboard_summary with (security_invoker = true) as
select
  (select count(*) from customers)                                          as total_customers,
  (select count(*) from loans where status in ('active','overdue'))         as active_loans,
  (select count(*) from loans where disbursement_date is not null)          as loans_disbursed,
  (select coalesce(sum(principal_amount),0) from loans where disbursement_date is not null) as amount_disbursed,
  (select coalesce(sum(amount),0) from payments
     where date_trunc('month', payment_date) = date_trunc('month', today_ist())) as collections_this_month,
  (select coalesce(sum(principal_outstanding),0) from v_loan_outstanding where status in ('active','overdue')) as principal_outstanding,
  (select coalesce(sum(overdue_amount),0) from v_loan_outstanding where status in ('active','overdue'))        as overdue_amount,
  (select count(*) from v_schedule_status where status = 'paid')            as paid_installments,
  (select count(*) from v_schedule_status where total_outstanding > 0)      as unpaid_installments,
  (select count(*) from v_schedule_status where status = 'overdue')         as overdue_installments,
  (select count(*) from vehicles where insurance_expiry < today_ist())      as expired_insurance,
  (select count(*) from vehicles where insurance_expiry between today_ist() and today_ist() + 30) as insurance_expiring_30d,
  (select count(*) from documents where status in ('uploaded','pending_review')) as documents_to_verify,
  (select count(*) from v_loan_file_status where missing_count > 0)         as incomplete_loan_files,
  (select count(*) from follow_up_tasks where status = 'open' and due_date <= today_ist()) as follow_ups_due;

-- ───────────── security ─────────────
alter table required_document_rules enable row level security;
alter table follow_up_tasks enable row level security;
create policy rules_select on required_document_rules for select to authenticated using (financier_id = auth_financier_id());
create policy rules_insert on required_document_rules for insert to authenticated with check (financier_id = auth_financier_id() and auth_role() = 'owner');
create policy rules_delete on required_document_rules for delete to authenticated using (financier_id = auth_financier_id() and auth_role() = 'owner');
create policy tasks_select on follow_up_tasks for select to authenticated using (financier_id = auth_financier_id());
create policy tasks_insert on follow_up_tasks for insert to authenticated with check (financier_id = auth_financier_id());
create policy tasks_update on follow_up_tasks for update to authenticated using (financier_id = auth_financier_id()) with check (financier_id = auth_financier_id());

revoke all on all tables in schema public from anon;
revoke all on required_document_rules, follow_up_tasks, v_alerts, v_loan_missing_documents, v_loan_file_status from authenticated;
grant select on required_document_rules, follow_up_tasks, v_alerts, v_loan_missing_documents, v_loan_file_status to authenticated;
grant insert, delete on required_document_rules to authenticated;
grant insert, update on follow_up_tasks to authenticated;
